INSERT INTO public.social_media_posts (day, title, description, theme, category, user_id, status) VALUES
(1, 'What is an RCM contract?', 'A Revenue Cycle Management contract defines how a healthcare provider and a payer agree on reimbursement, responsibilities, covered services, and timelines. It''s the foundation for clean claims and appeals.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(2, 'What''s the difference between a payer contract and a patient benefit?', 'Payer contracts are agreements between providers and insurers, while benefits are tied to individual patient plans. A service can be covered in the contract but denied if the patient''s plan doesn''t include it.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(3, 'What are fee schedules and why do they matter?', 'Fee schedules specify how much a payer reimburses for each CPT/HCPCS code. Providers use these to calculate expected payments and detect underpayments or short pays.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(4, 'When does a claim need authorization?', 'Some outpatient services (like MRIs or infusions) require prior authorization. Payer contracts often define which services need approval before care is delivered.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(5, 'How do timely filing limits impact revenue?', 'Contracts often require claims to be submitted within 90–180 days. Missing this deadline usually leads to non-payable denials with little to no appeal opportunity.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(6, 'Why would a contracted service still be denied?', 'Even if covered, services can be denied for missing auth, incorrect coding, or insufficient documentation. Knowing contract requirements is key to prevention.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(7, 'What is a ''clean claim''?', 'A clean claim is correctly coded, documented, and submitted within contract requirements—processed and paid without edits or denials.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(8, 'What is a ''contractual adjustment''?', 'The contractual adjustment is the amount written off by the provider per the agreement. It''s the difference between billed charges and allowed reimbursement.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(9, 'How are outpatient denials tracked?', 'Denials are categorized by type (auth, coding, eligibility, etc.), and monitored via CARC/RARC codes in remittance data for trend analysis.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(10, 'What is a contract management system?', 'It''s a tool used to store, track, and calculate expected payments per payer agreements. It helps RCM teams spot underpayments and rule-based denials.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(11, 'What are common outpatient denial types?', 'Top denials include missing authorization, medical necessity, coding mismatches, and benefit coverage issues—often preventable with upfront checks.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(12, 'What is the appeals process for denied claims?', 'Most contracts allow 1–2 levels of appeal. Providers must submit supporting clinical evidence and cite contractual grounds within a specific window (e.g., 60 days).', 'Contracts', 'contracts', auth.uid(), 'draft'),
(13, 'Why do payers deny claims for medical necessity?', 'Even covered services can be denied if the payer decides clinical documentation doesn''t justify the need. Appeals must be supported with strong evidence.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(14, 'What''s a utilization management clause?', 'These clauses define how and when services must be reviewed before approval. Missing steps (like peer review) may lead to claim denials.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(15, 'What is a retro-authorization?', 'Some payers allow providers to request authorization after care (within a short window). This is usually reserved for urgent or overlooked cases.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(16, 'Why are modifiers important in outpatient claims?', 'CPT modifiers affect reimbursement and claim logic. Missing or incorrect ones can cause denials or inaccurate payments—despite contractual coverage.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(17, 'Can claims be denied for being duplicates?', 'Yes. If a provider accidentally bills the same service more than once (even across systems), payers will reject it. Contract terms may outline re-bill rules.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(18, 'What is coordination of benefits (COB)?', 'COB refers to determining the correct payer order. Incorrect COB settings often cause outpatient denials that require rebilling or patient follow-up.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(19, 'Can I appeal a denial if the contract was misapplied?', 'Yes. Providers often cite contract language in appeals to overturn errors like rate misapplications or incorrect bundling edits.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(20, 'What is a payer edit policy?', 'These are payer-specific rules that apply on top of national standards. Contracts may include or reference them, and failing to follow them may trigger denials.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(21, 'How do I track underpayments?', 'Use remittance data and contract fee schedules to compare expected vs. actual payments. Gaps over allowed variance should be flagged and disputed.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(22, 'What''s the difference between a hard and soft denial?', 'Hard denials are final (e.g. timely filing missed); soft denials can be corrected or appealed (e.g. missing auth, wrong modifier).', 'Contracts', 'contracts', auth.uid(), 'draft'),
(23, 'How do patient coverage limits impact contracts?', 'Even if a contract includes a service, the patient''s individual benefit limit may exclude it—resulting in a valid denial unless appealed successfully.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(24, 'What are CARC and RARC codes?', 'CARC = Claim Adjustment Reason Code; RARC = Remittance Advice Remark Code. These codes help explain payer denials and are critical for rework and appeals.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(25, 'What is a provider''s obligation in an audit?', 'Some contracts include audit clauses allowing payers to retrospectively review claims. Denials or take-backs can result if documentation is weak.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(26, 'What is downcoding?', 'It''s when the payer lowers the code level on a claim (e.g. Level 4 → Level 3 E/M). Contracts may allow or limit this depending on documentation.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(27, 'How are outpatient bundled services handled?', 'Some outpatient services are bundled under a primary code. Billing a component separately may be denied per contract rules or CCI edits.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(28, 'Can payment timelines be enforced?', 'Yes—most contracts require payers to reimburse ''clean claims'' within 30–45 days. Delays beyond that may be escalated under the contract terms.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(29, 'Why should we meet with payers regularly?', 'Quarterly payer-provider meetings help resolve recurring denials, clarify contract interpretations, and improve collaboration for both parties.', 'Contracts', 'contracts', auth.uid(), 'draft'),
(30, 'What metrics should we track for RCM contracts?', 'Track denial rate, appeal overturn rate, underpayment rate, average days to payment, and clean claim rate—all tied back to contract compliance.', 'Contracts', 'contracts', auth.uid(), 'draft');